    30  /**
    31   * Fuzzing entry point. This function is passed a buffer containing a test
    32   * case.  This test case should drive the CURL API into making a request.
    33   */
    34  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    35  {
    36    int rc = 0;
    37    int tlv_rc;
    38    FUZZ_DATA fuzz;
    39    TLV tlv;
    40
    41    /* Ignore SIGPIPE errors. We'll handle the errors ourselves. */
    42    signal(SIGPIPE, SIG_IGN);
    43
    44    /* Have to set all fields to zero before getting to the terminate function */
    45    memset(&fuzz, 0, sizeof(FUZZ_DATA));
    46
    47    if(size < sizeof(TLV_RAW)) {
    48      /* Not enough data for a single TLV - don't continue */
    49      goto EXIT_LABEL;
    50    }
    51
    52    /* Try to initialize the fuzz data */
    53    FTRY(fuzz_initialize_fuzz_data(&fuzz, data, size));
    54
    55    for(tlv_rc = fuzz_get_first_tlv(&fuzz, &tlv);
    56        tlv_rc == 0;
    57        tlv_rc = fuzz_get_next_tlv(&fuzz, &tlv)) {
    58
    59      /* Have the TLV in hand. Parse the TLV. */
    60      rc = fuzz_parse_tlv(&fuzz, &tlv);
    61
    62      if(rc != 0) {
    63        /* Failed to parse the TLV. Can't continue. */
    64        goto EXIT_LABEL;
    65      }
    66    }
    67
    68    if(tlv_rc != TLV_RC_NO_MORE_TLVS) {
    69      /* A TLV call failed. Can't continue. */
    70      goto EXIT_LABEL;
    71    }
    72
    73    /* Set up the standard easy options. */
    74    FTRY(fuzz_set_easy_options(&fuzz));
    75
    76    /**
    77     * Add in more curl options that have been accumulated over possibly
    78     * multiple TLVs.
    79     */
    80    if(fuzz.header_list != NULL) {
    81      curl_easy_setopt(fuzz.easy, CURLOPT_HTTPHEADER, fuzz.header_list);
    82    }
    83
    84    if(fuzz.mail_recipients_list != NULL) {
    85      curl_easy_setopt(fuzz.easy, CURLOPT_MAIL_RCPT, fuzz.mail_recipients_list);
    86    }
    87
    88    if(fuzz.mime != NULL) {
    89      curl_easy_setopt(fuzz.easy, CURLOPT_MIMEPOST, fuzz.mime);
    90    }
    91
    92    /* Run the transfer. */
    93    fuzz_handle_transfer(&fuzz);
    94
    95  EXIT_LABEL:
    96
    97    fuzz_terminate_fuzz_data(&fuzz);
    98
    99    /* This function must always return 0. Non-zero codes are reserved. */
   100    return 0;
   101  }
